-- 0133_district_master_centroids.sql
-- Why: the customer service-area gate resolves a reverse-geocoded address against the active
-- district master. Platform geocoders often omit the revenue district (`subAdminArea` /
-- `subAdministrativeArea` can be null — a Lalgudi origin reports city "Lalgudi", sub-locality
-- "sirudayur" and no district), so name-only matching can block a genuinely covered user. A
-- district centroid lets the app resolve the nearest active district from the origin coordinates
-- it already holds, used only as a fallback after the name match fails.
--
-- Source: scripts/district-seed.json (the same verified Google centroids 0127 was generated from).
-- Keyed on google_place_id, the durable identity, so legacy codes (TNA/TCH/TTC…) and generated
-- codes (AP01…) both backfill correctly. Additive, nullable, idempotent: safe to re-run.
--
-- Authority: docs/architecture/db-schema.md §12.42, monolith-breakdown.md §1 (districts row),
--            docs/user-interaction-workflow/customer/onboarding/service-area-gate.md.

alter table admins.district_master
  add column if not exists latitude  double precision,
  add column if not exists longitude double precision;

comment on column admins.district_master.latitude is
  'District centroid latitude from scripts/district-seed.json. Used as a coordinate fallback when a reverse-geocoded address omits the district name; never a coverage boundary.';
comment on column admins.district_master.longitude is
  'District centroid longitude from scripts/district-seed.json (see latitude).';

update admins.district_master dm
   set latitude  = v.latitude,
       longitude = v.longitude
  from (values
